#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 2005;
const long long oo = 1e18;

int n;
int a[N], pre[N];
long long f[N];

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        pre[i] = pre[i - 1] + a[i];
    }
    for (int i = 1; i <= n; i++) {
        f[i] = oo;
        for (int j = 0; j < i; j++)
            f[i] = min(f[i], f[j] + 1ll * (pre[i] - pre[j]) * (pre[i] - pre[j]));
    }
    printf("%lld\n", f[n]);
    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 2e4 + 5;
const int E = N << 1;

int n;
int h[N], to[E], nx[E], et;
int ans;

void ae(int u, int v) {
    et++;
    to[et] = v;
    nx[et] = h[u];
    h[u] = et;
}

int dfs(int u, int p=0) {
    int sz = 1;
    for (int i = h[u]; i; i = nx[i])
        if (to[i] != p)
            sz += dfs(to[i], u);
    ans = min(ans, abs(n - 2 * sz));
    return sz;
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i < n; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        ae(u, v);
        ae(v, u);
    }
    ans = n;
    dfs(1);
    printf("%d\n", ans);
    return 0;
}
